#!/usr/bin/env bash
# Rechecks every observation of the table-driven checker.
#
# An observation file (Checkers/TCheck/**/Observed/*.lean, generated by
# gocheck/tcheck) records, in its single axiom, the bytes tcheck.Check
# answered true on.  For each one this script
#
#   1. reruns tcheck.Check on exactly those bytes (gocheck/tcheck -verify), and
#   2. reruns the command recorded in the file's header, which reifies the
#      code again, runs the checker again and rewrites the file (and the
#      table file),
#
# and then fails if any generated file changed: the regenerated output must
# be identical to what was there before.  Generated files that git does not
# track yet are compared against a copy taken before regenerating.
#
# Run from the repository root: bash gocheck/tcheck/observe.sh
set -euo pipefail

if [ ! -d .lake/packages/perennial ]; then
	echo "missing .lake/packages/perennial (go.mod's replacement for perennial):" >&2
	echo "run 'lake build' first, which fetches the Lake dependencies" >&2
	exit 2
fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
go build -o "$tmp/tcheck" ./gocheck/tcheck

mapfile -t files < <(find Checkers/TCheck -path '*/Observed/*.lean' -type f | sort | while read -r f; do
  head -2 "$f" | grep -q '^Generated by gocheck/tcheck' && echo "$f"; done)
if [ ${#files[@]} -eq 0 ]; then
  echo "observe.sh: no observation files" >&2
  exit 1
fi
mapfile -t tables < <(find Checkers/TCheck -name 'Table*.lean' -type f | sort | while read -r f; do
  head -2 "$f" | grep -q '^Generated by gocheck/tcheck' && echo "$f"; done)

# Snapshot every generated file, to compare after regenerating.
for f in "${files[@]}" "${tables[@]}"; do
  mkdir -p "$tmp/before/$(dirname "$f")"
  cp "$f" "$tmp/before/$f"
done

regen=()
for f in "${files[@]}"; do
  "$tmp/tcheck" -verify "$f"
  cmd=$(sed -n 's/^     go run \.\/gocheck\/tcheck //p' "$f" | head -1)
  [ -n "$cmd" ] || { echo "observe.sh: $f: no command in the header" >&2; exit 1; }
  regen+=("$cmd")
done
for cmd in "${regen[@]}"; do
  # shellcheck disable=SC2086
  "$tmp/tcheck" $cmd
done

changed=0
for f in "${files[@]}" "${tables[@]}"; do
  if ! cmp -s "$tmp/before/$f" "$f"; then
    echo "observe.sh: regenerating changed $f" >&2
    diff -u "$tmp/before/$f" "$f" | head -20 >&2 || true
    changed=1
  fi
done
[ $changed -eq 0 ] || exit 1
echo "observe.sh: ${#files[@]} observation(s) rechecked and regenerated identically"
